/// <summary>
/// R005_作業依頼書サブ 画面を開く時 — 画面の初期表示の処理
/// </summary>
public async Task<R005WorkRequestSubResponse> GetInitialDataAsync(R005WorkRequestSubRequest request)
{
    try
    {
        // Args: 登録番号Bｆ → request.RegistrationNumberBf; 登録番号B → request.RegistrationNumberB
        // R005_作業依頼書サブ → BuildingAfterCollectionRepository.AfterMaintenanceReceptionAsync (query: Q005_アフターメンテナンス受付)
        var afterMaintenanceReception = await _buildingAfterCollectionRepository.AfterMaintenanceReceptionAsync(request.RegistrationNumberBf, request.RegistrationNumberB);

        return new R005WorkRequestSubResponse {
            Success = true,
            Data = afterMaintenanceReception,
        };
    }
    catch (System.Exception ex)
    {
        return new R005WorkRequestSubResponse { Success = false, Message = ex.Message };
    }
}
